create function public.search_songs(p_q text default '',p_categories text[] default '{}',p_min integer default null,p_max integer default null,p_unrated boolean default false,p_sort text default 'title',p_page integer default 1,p_size integer default 20,p_admin boolean default false,p_visibility text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if p_admin then perform public.assert_admin();end if;
 with filtered as(select s.* from public.songs s where (p_admin or s.is_visible) and (not p_admin or p_visibility='' or (p_visibility='public' and s.is_visible) or (p_visibility='private' and not s.is_visible)) and (p_q='' or (s.search_text like '%'||p_q||'%' and position(p_q in s.search_text)>0)) and (not p_unrated or s.difficulty_steps is null) and (p_min is null or s.difficulty_steps>=p_min) and (p_max is null or s.difficulty_steps<=p_max) and (cardinality(p_categories)=0 or exists(select 1 from public.song_category_links l join public.song_categories c on c.id=l.category_id where l.song_id=s.id and c.active and c.slug=any(p_categories)) or ('unclassified'=any(p_categories) and not exists(select 1 from public.song_category_links l join public.song_categories c on c.id=l.category_id where l.song_id=s.id and c.active)))),paged as(select * from filtered order by case when p_sort='artist' then artist_sort end collate "C",case when p_sort='difficulty_asc' then difficulty_steps end asc nulls last,case when p_sort='difficulty_desc' then difficulty_steps end desc nulls last,case when p_sort='newest' then created_at end desc,title_sort collate "C",artist_sort collate "C",id limit least(greatest(p_size,1),100) offset (greatest(p_page,1)-1)*least(greatest(p_size,1),100)),objects as(select jsonb_build_object('id',s.id,'title',s.title,'artist',s.artist_name,'album',s.album_title,'versionLabel',s.version_label,'release',s.release_date_text,'steps',s.difficulty_steps,'note',s.difficulty_note,'categories',coalesce((select jsonb_agg(c.name order by c.display_order,c.name) from public.song_category_links l join public.song_categories c on c.id=l.category_id where l.song_id=s.id and (p_admin or c.active)),'[]'),'original',(select url from public.song_youtube_links where song_id=s.id and kind='original'),'karaoke',(select url from public.song_youtube_links where song_id=s.id and kind='karaoke'),'cover',s.cover_url,'coverSource',s.cover_source_url,'coverAlt',s.cover_alt,'visible',s.is_visible,'version',s.version,'createdAt',s.created_at) || case when p_admin then jsonb_build_object('memo',coalesce((select memo from public.song_admin_metadata where song_id=s.id),''),'coverUsageBasis',coalesce((select cover_usage_basis from public.song_admin_metadata where song_id=s.id),'')) else '{}' end as obj from paged s) select jsonb_build_object('rows',coalesce((select jsonb_agg(obj) from objects),'[]'),'total',(select count(*) from filtered)) into result;return result;end$$;
revoke all on function public.search_songs(text,text[],integer,integer,boolean,text,integer,integer,boolean,text) from public;
grant execute on function public.search_songs(text,text[],integer,integer,boolean,text,integer,integer,boolean,text) to anon,authenticated;
create function public.request_retry(p_key uuid,p_data jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare r public.operation_keys;begin select * into r from public.operation_keys where scope='service:request.submit' and key=p_key;if not found then return null;end if;if r.payload_hash<>encode(sha256(convert_to(p_data::text,'UTF8')),'hex') then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='23505';end if;return r.result;end$$;
revoke all on function public.request_retry(uuid,jsonb) from public;
grant execute on function public.request_retry(uuid,jsonb) to service_role;
